import java.util.List;
import java.lang.reflect.Method;

public class KmpTest {
    public static void main(String[] args) throws Exception {
        Method search = Class.forName("KMPSearch").getDeclaredMethod("search", String.class, String.class);
        search.setAccessible(true);
        check("baseline", search.invoke(null, "aaba", "aabaacaadaabaaba"), "[0, 9, 12]");
        check("overlap",  search.invoke(null, "aa", "aaaa"), "[0, 1, 2]");
        check("empty pat",search.invoke(null, "", "abc"), "[]");
        check("pat>text", search.invoke(null, "abcd", "ab"), "[]");
        check("no match", search.invoke(null, "xyz", "abcabc"), "[]");
        check("full",     search.invoke(null, "abc", "abc"), "[0]");
        try { search.invoke(null, null, "x"); System.out.println("FAIL null: no exception"); }
        catch (Exception e) { System.out.println("PASS null -> " + e.getCause().getClass().getSimpleName()); }
    }
    static void check(String name, Object got, String want) {
        System.out.println((want.equals(got.toString()) ? "PASS " : "FAIL ") + name + " -> " + got);
    }
}
